// src/App.js — Section đọc cấp hiện tại rồi cung cấp cấp + 1 cho cây con
import { createContext, useContext } from 'react';

const LevelContext = createContext(0);

function Section({ children }) {
  const level = useContext(LevelContext);
  return (
    <section>
      <LevelContext.Provider value={level + 1}>{children}</LevelContext.Provider>
    </section>
  );
}

function Heading({ children }) {
  const level = Math.min(Math.max(useContext(LevelContext), 1), 6);
  const Tag = `h${level}`; // tên biến VIẾT HOA để JSX hiểu là thẻ động
  return <Tag>{children}</Tag>;
}

export default function App() {
  return (
    <Section>
      <Heading>Front-end</Heading>
      <Section>
        <Heading>React</Heading>
        <Section>
          <Heading>Hooks</Heading>
          <Heading>Context</Heading>
        </Section>
      </Section>
      <Section>
        <Heading>Tools</Heading>
      </Section>
    </Section>
  );
}

